<?php $title="Add Lead";require "includes/header.php";if($_SERVER["REQUEST_METHOD"]==="POST"){$s=$conn->prepare("INSERT INTO leads(name,phone,interest,source,score,status) VALUES(?,?,?,?,?,?)");$score=(int)$_POST["score"];$s->bind_param("ssssis",$_POST["name"],$_POST["phone"],$_POST["interest"],$_POST["source"],$score,$_POST["status"]);$s->execute();go("leads.php");}?><div class="card"><h2>Add Lead</h2><form method="post"><label>Name</label><input name="name" required><label>Phone</label><input name="phone"><label>Interest</label><input name="interest" placeholder="MTB / E-bike / Road"><label>Source</label><select name="source"><option>Website</option><option>Instagram</option><option>Walk-in</option><option>Referral</option></select><label>AI Score</label><input name="score" type="number" min="0" max="100" value="75"><label>Status</label><select name="status"><option>New</option><option>Contacted</option><option>Hot</option><option>Converted</option></select><button class="btn primary">Save Lead</button></form></div><?php require "includes/footer.php";?>